    private static final String PROFILE="native-cytometry-intensity-unbinned-v1";
    private static final String GATE_PROFILE="native-flowjo10-wsp20-flowkit132-v1";
    private static final String SCOPE="Complete unweighted, unbinned measurement statistics with explicit R_TYPE_7 quantiles. Fresh gating must match every captured parent membership and count. Measurement space is explicitly AMPLIFIER_MEASUREMENT or WSP_COMPENSATED_MEASUREMENT. No display-transform binning, imported Statistic-node result, FlowJo vendor-statistics equivalence, cell-cycle fit, clustering plugin, inferred MFI definition or whole-paper reproduction.";
    private static final String ACTION="Require exit 0, COMPLETED.json and result_admitted=true. SKIP3: supply the named permitted input/capability or use the supported explicit method; vendor binning/settings are unavailable and are never inferred. FAIL2: no complete result; preserve inputs and partial output, correct the named integrity, membership, numerical or capacity problem, then retry NEW output. Undefined statistic values remain null with explicit reason/counts; no clipping, dropped event, pseudocount or nonfinite-value replacement. MFI must be defined as mean, median or geometric mean on a declared measurement scale. VERIFY checks bytes only; REPLAY freshly gates and recomputes statistics using the exact producer JAR.";
    private record Definition(String id,List<String> gatePath,String parameter,String domain,List<CytometryIntensitySummary.Statistic> statistics,int gate,int column,double[] values) { }
    private static final class Unsupported extends IOException {
        private static final long serialVersionUID=1L;
        Unsupported(String message) { super(message); }
    }
    public static int run(String[] args,PrintStream output,PrintStream error) {
        Path owned=null;
        try {
            if(args.length==0||args.length==1&&args[0].equals("--help")) {
                output.println("flowjo-tools SUMMARIZE --request statistics.json\nflowjo-tools SUMMARIZE VERIFY --run completed-directory\nflowjo-tools SUMMARIZE REPLAY --run completed-directory --out NEW-directory\n"+SCOPE+"\n"+ACTION+"\nSee docs/CYTOMETRY_INTENSITY.md for the complete request and definitions.");return 0;
            }
            if(args.length==3&&args[0].equals("VERIFY")&&args[1].equals("--run")){verify(Path.of(args[2]));output.println("PASS intensity capture integrity only; no fit rerun. "+ACTION);output.flush();return output.checkError()?2:0;}
            if(args.length==5&&args[0].equals("REPLAY")&&args[1].equals("--run")&&args[3].equals("--out")) {
                Path prior=Path.of(args[2]).toAbsolutePath().normalize();verify(prior);Map<?,?> producer=object(prior.resolve("producer.json"));require(NextflowFiles.fingerprint(producer.get("jar"),1L<<31).equals(NextflowFiles.pin(jar(),1L<<31,()->{})),"Restore the exact original producer JAR for intensity replay");
                var request=new LinkedHashMap<Object,Object>(object(prior.resolve("replay-request.json")));request.put("parent",prior.resolve("parent").toString());Path target=destination(Path.of(args[4]).toAbsolutePath().normalize(),List.of(prior));request.put("out",target.toString());Files.createDirectories(target.getParent());Files.createDirectory(target);owned=target;NextflowFiles.writeJson(target.resolve("replay-invocation.json"),request);return summarize(target.resolve("replay-invocation.json"),request,target,output,error);
            }
            require(args.length==2&&args[0].equals("--request"),"Use SUMMARIZE --request JSON, VERIFY --run directory or REPLAY --run directory --out NEW");Path request=regular(Path.of(args[1]));return summarize(request,object(request),null,output,error);
        }catch(Exception failure){return failed(owned,failure,error);}
    }
